SELECT ?name ?tsid WHERE {
  ?p ref:hasExternalReference ?ext .
  ?p ref:hasTimeseriesId ?tsid .
  ?p rdfs:label ?name .
  FILTER (?name IN ("Chiller02","HWPump02","SupplyFan_AHU03"))
}

SELECT ?iri ?cls WHERE {
  ?p a ?cls .
  ?p rdfs:label ?lbl .
  FILTER (regex(?lbl, "Chiller|HWPump|SupplyFan", "i"))
  LIMIT 50
}

SELECT ?uri ?lbl WHERE {
  ?uri a ?cls .
  OPTIONAL { ?uri rdfs:label ?lbl }
  FILTER (regex(STR(?uri), "chiller|pump|fan|ahu|hw", "i"))
}

